<?php
namespace Tests\Feature;
use Tests\TestCase;use App\Services\Marketing\MarketingTargetGrounding;
class MarketingTargetGroundingTest extends TestCase {
 private function samples():array{return array_map(fn($f)=>['id'=>'S'.$f,'scene_number'=>1,'frame'=>$f,'raw_sha256'=>str_repeat('a',64)], [0,12,24,36,48]);}
 private function target(string $mode='static'):array {return ['target_id'=>'product','mode'=>$mode,'start_frame'=>0,'end_frame'=>49,'kind'=>'circle','observations'=>array_map(fn($s)=>['sample_id'=>$s['id'],'bbox'=>[.5,.3,.3,.3],'confidence'=>'high','visible'=>true,'identity_match'=>true,'people'=>[]],$this->samples())];}
 public function test_static_grounding_requires_real_anchors_and_keeps_source_identity():void {$r=app(MarketingTargetGrounding::class)->validate($this->target(),['number'=>1,'frames'=>49,'raw_sha256'=>str_repeat('a',64)],$this->samples());$this->assertSame('static',$r['mode']);$this->assertSame(5,count($r['points']));$this->assertSame(str_repeat('a',64),$r['source_sha256']);}
 public function test_wrong_identity_occlusion_foreign_sample_and_bounds_are_rejected():void {$service=app(MarketingTargetGrounding::class);foreach(['identity_match','visible'] as $k){$t=$this->target();$t['observations'][1][$k]=false;$this->assertNull($service->validate($t,['number'=>1,'frames'=>49,'raw_sha256'=>str_repeat('a',64)],$this->samples()));}$t=$this->target();$t['observations'][0]['bbox']=[.9,.3,.3,.3];$this->assertNull($service->validate($t,['number'=>1,'frames'=>49,'raw_sha256'=>str_repeat('a',64)],$this->samples()));$t=$this->target();$t['observations'][0]['sample_id']='foreign';$this->assertNull($service->validate($t,['number'=>1,'frames'=>49,'raw_sha256'=>str_repeat('a',64)],$this->samples()));}
 public function test_motion_gap_jump_and_short_supported_interval_are_rejected():void {$s=app(MarketingTargetGrounding::class);$scene=['number'=>1,'frames'=>49,'raw_sha256'=>str_repeat('a',64)];$this->assertNotNull($s->validate($this->target('moving'),$scene,$this->samples()));$t=$this->target('moving');array_splice($t['observations'],2,1);$this->assertNull($s->validate($t,$scene,$this->samples()));$t=$this->target('moving');$t['observations'][1]['bbox']=[.05,.3,.3,.3];$this->assertNull($s->validate($t,$scene,$this->samples()));}
 public function test_static_drift_over_two_percent_is_rejected():void {$t=$this->target();$t['observations'][4]['bbox'][0]+=.021;$this->assertNull(app(MarketingTargetGrounding::class)->validate($t,['number'=>1,'frames'=>49,'raw_sha256'=>str_repeat('a',64)],$this->samples()));}
 public function test_exact_static_iou_and_drift_boundary_and_beyond():void {$s=app(MarketingTargetGrounding::class);$scene=['number'=>1,'frames'=>49,'raw_sha256'=>str_repeat('a',64)];$t=$this->target();foreach($t['observations'] as &$o)$o['bbox']=[.4,.3,.18,.3];unset($o);$t['observations'][4]['bbox'][0]=.42;$this->assertEqualsWithDelta(.8,MarketingTargetGrounding::iou($t['observations'][0]['bbox'],$t['observations'][4]['bbox']),1e-8);$this->assertNotNull($s->validate($t,$scene,$this->samples()));$t['observations'][4]['bbox'][0]=.4201;$this->assertNull($s->validate($t,$scene,$this->samples()));}
 public function test_motion_exact_area_and_distance_boundaries():void {$s=app(MarketingTargetGrounding::class);$scene=['number'=>1,'frames'=>49,'raw_sha256'=>str_repeat('a',64)];$t=$this->target('moving');$t['observations'][1]['bbox']=[.4625,.3,.375,.3];$this->assertNotNull($s->validate($t,$scene,$this->samples()));$t['observations'][1]['bbox'][2]=.3751;$this->assertNull($s->validate($t,$scene,$this->samples()));$t=$this->target('moving');foreach($t['observations'] as &$o)$o['bbox']=[.2,.3,.15,.15];unset($o);$t['observations'][1]['bbox'][0]+=.1*hypot(720,1280)/720;$this->assertNotNull($s->validate($t,$scene,$this->samples()));$t['observations'][1]['bbox'][0]+=.0001;$this->assertNull($s->validate($t,$scene,$this->samples()));}
}
